param(
    [string]$ProjectRoot = "D:\simras-digital-twin-repository\simras-digital-twin"
)

$ErrorActionPreference = "Stop"
Set-Location $ProjectRoot
[Environment]::CurrentDirectory = (Get-Location).Path

Write-Host "`n============================================================" -ForegroundColor Cyan
Write-Host "SIMRAS REAL-DATA + REPORTS ALL-IN-ONE" -ForegroundColor Cyan
Write-Host "============================================================" -ForegroundColor Cyan

$stamp = Get-Date -Format "yyyyMMdd_HHmmss"
$backup = Join-Path $ProjectRoot "archive\real_data_all_in_one_$stamp"
New-Item -ItemType Directory -Force $backup | Out-Null

$utf8 = New-Object System.Text.UTF8Encoding($false)

function Write-B64 {
    param([string]$Path, [string]$Data)
    $parent = Split-Path -Parent $Path
    if ($parent -and -not (Test-Path $parent)) {
        New-Item -ItemType Directory -Force $parent | Out-Null
    }
    [IO.File]::WriteAllBytes($Path, [Convert]::FromBase64String($Data))
}

Write-Host "[1/10] Backing up current frontend/backend..." -ForegroundColor Cyan

$targets = @(
    ".\frontend\src\layouts\DashboardLayout.tsx",
    ".\frontend\src\services\api.ts",
    ".\frontend\src\services\index.ts",
    ".\frontend\src\services\authService.ts",
    ".\frontend\src\components\landing\AISection.tsx",
    ".\frontend\src\pages\dashboard\DashboardPage.tsx",
    ".\frontend\src\pages\ai\AIPages.tsx",
    ".\frontend\src\pages\ai\AnalyticsPage.tsx",
    ".\frontend\src\pages\notifications\NotificationsPage.tsx",
    ".\frontend\src\pages\reports\ReportsPages.tsx",
    ".\frontend\src\data\analyticsData.ts",
    ".\frontend\src\data\infrastructureData.ts",
    ".\backend\app\api\routes\ui_compat.py"
)

foreach ($file in $targets) {
    if (Test-Path $file) {
        $safe = ($file.TrimStart(".\")).Replace("\","__")
        Copy-Item $file (Join-Path $backup $safe) -Force
    }
}

Write-Host "Backup: $backup" -ForegroundColor DarkGray

Write-Host "[2/10] Repairing DashboardLayout parser issue..." -ForegroundColor Cyan

@'
from pathlib import Path
import re

p = Path("frontend/src/layouts/DashboardLayout.tsx")
if not p.exists():
    raise SystemExit("DashboardLayout.tsx not found")

text = p.read_text(encoding="utf-8-sig")

pattern = re.compile(
    r'(<span[^>]*className="[^"]*grid size-8 place-items-center rounded-full[^"]*"[^>]*>).*?(</span>)',
    re.DOTALL,
)
replacement = r'\1\n                  {user?.name?.charAt(0) ?? "S"}\n                \2'
text, count = pattern.subn(replacement, text, count=1)

text = re.sub(
    r'\{\s*user\?\.name\?\.charAt\(0\).*?\}',
    '{user?.name?.charAt(0) ?? "S"}',
    text,
    count=1,
    flags=re.DOTALL,
)

p.write_text(text, encoding="utf-8")
print("DashboardLayout avatar repaired; replacements:", count)
'@ | py -

Write-Host "[3/10] Replacing active mock/fabricated frontend data paths..." -ForegroundColor Cyan

Write-B64 ".\frontend\src\services\api.ts" ""
Write-B64 ".\frontend\src\services\authService.ts" ""
Write-B64 ".\frontend\src\components\landing\AISection.tsx" ""
Write-B64 ".\frontend\src\pages\dashboard\DashboardPage.tsx" ""
Write-B64 ".\frontend\src\pages\ai\AIPages.tsx" ""
Write-B64 ".\frontend\src\pages\ai\AnalyticsPage.tsx" ""
Write-B64 ".\frontend\src\pages\notifications\NotificationsPage.tsx" ""
Write-B64 ".\frontend\src\pages\reports\ReportsPages.tsx" ""

foreach ($envFile in @(".\frontend\.env.development", ".\frontend\.env.production")) {
    $existing = if (Test-Path $envFile) { Get-Content $envFile -Raw } else { "" }
    if ($existing -notmatch "(?m)^VITE_API_BASE_URL=") {
        $existing = $existing.TrimEnd() + "`nVITE_API_BASE_URL=http://127.0.0.1:8000`n"
        [IO.File]::WriteAllText($envFile, $existing.TrimStart(), $utf8)
    }
}

if (Test-Path ".\frontend\src\services\index.ts") {
    $indexText = Get-Content ".\frontend\src\services\index.ts" -Raw
    $indexText = $indexText -replace ',\s*mockRequest', ''
    $indexText = $indexText -replace 'mockRequest\s*,\s*', ''
    [IO.File]::WriteAllText(".\frontend\src\services\index.ts", $indexText, $utf8)
}

foreach ($mock in @(
    ".\frontend\src\data\analyticsData.ts",
    ".\frontend\src\data\infrastructureData.ts"
)) {
    if (Test-Path $mock) {
        $safe = ($mock.TrimStart(".\")).Replace("\","__")
        Copy-Item $mock (Join-Path $backup $safe) -Force
        Remove-Item $mock -Force
    }
}

Write-Host "[4/10] Removing known fake defaults from remaining active UI..." -ForegroundColor Cyan

@'
from pathlib import Path

src = Path("frontend/src")

for p in src.rglob("*.tsx"):
    text = p.read_text(encoding="utf-8-sig")
    original = text

    text = text.replace(
        "builtYear: Number(asset.built_year ?? asset.age ?? 2000),",
        "builtYear: Number(asset.built_year ?? asset.age ?? 0),",
    )
    text = text.replace(
        "rulYears: Number(asset.remaining_useful_life ?? 10),",
        "rulYears: Number(asset.remaining_useful_life ?? 0),",
    )
    text = text.replace(
        "rulYears: Number(asset.remaining_useful_life ?? asset.remaining_life ?? 10),",
        "rulYears: Number(asset.remaining_useful_life ?? asset.remaining_life ?? 0),",
    )
    text = text.replace(
        "builtYear: Number(props.built_year ?? props.age ?? 2000),",
        "builtYear: Number(props.built_year ?? props.age ?? 0),",
    )
    text = text.replace(
        "rulYears: Number(props.remaining_useful_life ?? 10),",
        "rulYears: Number(props.remaining_useful_life ?? 0),",
    )

    if text != original:
        p.write_text(text, encoding="utf-8")

print("Known fake default scan completed.")
'@ | py -

Write-Host "[5/10] Extending backend live analytics/report APIs..." -ForegroundColor Cyan

@'
from pathlib import Path
import base64, re

p = Path("backend/app/api/routes/ui_compat.py")
if not p.exists():
    raise SystemExit("backend/app/api/routes/ui_compat.py not found")

text = p.read_text(encoding="utf-8-sig")

if "from sqlalchemy import desc, func, or_, select, text" not in text:
    text = text.replace(
        "from sqlalchemy import desc, func, or_, select",
        "from sqlalchemy import desc, func, or_, select, text",
    )

text = text.replace(
    'return round(sum(values) / len(values), 2) if values else 0.0',
    'return round(sum(values) / len(values), 2) if values else None',
)

if '"total_predictions": prediction_count' not in text:
    text = text.replace(
        'recent = sorted([a for a in payloads if a.get("prediction_time")], key=lambda a: a["prediction_time"], reverse=True)[:10]',
        'recent = sorted([a for a in payloads if a.get("prediction_time")], key=lambda a: a["prediction_time"], reverse=True)[:10]\n    prediction_count = int(await session.scalar(select(func.count()).select_from(Prediction)) or 0)',
    )
    text = text.replace(
        '"total_assets": len(payloads),',
        '"total_assets": len(payloads),\n        "total_predictions": prediction_count,',
        1,
    )

text = text.replace(
    '"risk_score": a["risk_score"], "health_score": a["health_score"] or 0, "remaining_life": a["remaining_useful_life"] or 0,',
    '"risk_score": a["risk_score"], "health_score": a["health_score"], "remaining_life": a["remaining_useful_life"], "confidence_score": a["prediction_confidence"],',
)
text = text.replace(
    '"risk_level": a["risk_level"], "health_score": a["health_score"] or 0, "last_assessed": a["prediction_time"],',
    '"risk_level": a["risk_level"], "health_score": a["health_score"], "last_assessed": a["prediction_time"],',
)

risk_pattern = re.compile(
    r'@router\.get\("/analytics/risk-analysis"\)\s*async def risk_analysis\(session: AsyncSession = Depends\(get_db\)\):.*?(?=\n\ndef _csv_response)',
    re.DOTALL,
)
risk_replacement = '''@router.get("/analytics/risk-analysis")
async def risk_analysis(session: AsyncSession = Depends(get_db)):
    assets = (await session.scalars(select(Asset))).all()
    predictions = await _prediction_index(session)
    payloads = [_asset_payload(a, predictions) for a in assets]

    risk_distribution = [
        {"key": "low", "name": "Low Risk", "value": sum(1 for a in payloads if a.get("risk_score") is not None and float(a["risk_score"]) < 40)},
        {"key": "medium", "name": "Medium Risk", "value": sum(1 for a in payloads if a.get("risk_score") is not None and 40 <= float(a["risk_score"]) < 70)},
        {"key": "high", "name": "High Risk", "value": sum(1 for a in payloads if a.get("risk_score") is not None and float(a["risk_score"]) >= 70)},
    ]

    district_map = {}
    type_map = {}
    for item in payloads:
        district = str(item.get("district") or "Unknown")
        asset_type = str(item.get("asset_type") or "other")
        for key, bucket in ((district, district_map), (asset_type, type_map)):
            row = bucket.setdefault(key, {"assets": 0, "high_risk": 0, "medium_risk": 0, "low_risk": 0})
            row["assets"] += 1
            score = item.get("risk_score")
            if score is None:
                continue
            if float(score) >= 70:
                row["high_risk"] += 1
            elif float(score) >= 40:
                row["medium_risk"] += 1
            else:
                row["low_risk"] += 1

    district_risk = [{"district": key, **value} for key, value in sorted(district_map.items())]
    asset_type_risk = [{"asset_type": key, **value} for key, value in sorted(type_map.items())]
    top = sorted(
        [a for a in payloads if a.get("risk_score") is not None],
        key=lambda a: float(a["risk_score"]),
        reverse=True,
    )[:50]

    return {
        "risk_distribution": risk_distribution,
        "district_risk": district_risk,
        "asset_type_risk": asset_type_risk,
        "top_high_risk_assets": top,
    }
'''
text, replaced = risk_pattern.subn(risk_replacement, text, count=1)
print("risk_analysis replaced:", replaced)

text = re.sub(
    r'\n# === SIMRAS_REAL_REPORTS_START ===.*?# === SIMRAS_REAL_REPORTS_END ===\n?',
    '\n',
    text,
    flags=re.DOTALL,
)

extension = base64.b64decode("").decode("utf-8")
text = text.rstrip() + "\n\n" + extension.strip() + "\n"
p.write_text(text, encoding="utf-8")
print("ui_compat.py patched")
'@ | py -

Write-Host "[6/10] Mock-data source audit..." -ForegroundColor Cyan

$mockHits = Get-ChildItem ".\frontend\src" -Recurse -File -Include *.ts,*.tsx |
    Select-String -Pattern `
        'DEMONSTRATION DATA',
        'Rajiv Bridge',
        'Central Ring Road',
        'Municipal Administration Building',
        'R² 0\.966',
        '94\.2%',
        'mockRequest',
        'operator@simras\.local',
        '98765 43210',
        'Math\.min\(99'

if ($mockHits) {
    Write-Host "Remaining suspicious strings (review only; build continues):" -ForegroundColor Yellow
    $mockHits | Select-Object Path,LineNumber,Line | Format-Table -Wrap
} else {
    Write-Host "Active frontend mock marker scan: CLEAN" -ForegroundColor Green
}

Write-Host "[7/10] Compiling backend + building frontend..." -ForegroundColor Cyan

py -m py_compile `
    ".\backend\app\api\routes\ui_compat.py" `
    ".\backend\app\main.py"

if ($LASTEXITCODE -ne 0) {
    throw "BACKEND PYTHON COMPILE FAILED"
}

Push-Location ".\frontend"
npm run build
$frontExit = $LASTEXITCODE
Pop-Location

if ($frontExit -ne 0) {
    throw "FRONTEND BUILD FAILED - backup is $backup"
}

Write-Host "[8/10] Rebuilding backend/frontend images..." -ForegroundColor Cyan

docker compose build backend frontend
if ($LASTEXITCODE -ne 0) {
    throw "DOCKER IMAGE BUILD FAILED"
}

Write-Host "[9/10] Route preflight before replacing running containers..." -ForegroundColor Cyan

docker compose run --rm --no-deps backend python -c "from app.main import app; p={getattr(r,'path','') for r in app.routes}; req=['/api/v1/dashboard/overview','/api/v1/reports/catalog','/api/v1/reports/portfolio/pdf','/api/v1/reports/model-governance/pdf','/api/v1/reports/high-risk/csv','/api/v1/analytics/risk-analysis']; m=[x for x in req if x not in p]; print('route_preflight=', 'PASS' if not m else 'FAIL', 'missing=',m); raise SystemExit(1 if m else 0)"

if ($LASTEXITCODE -ne 0) {
    throw "BACKEND ROUTE PREFLIGHT FAILED - running containers were not replaced"
}

docker compose up -d --force-recreate backend frontend
Start-Sleep -Seconds 8

Write-Host "[10/10] Live smoke tests..." -ForegroundColor Cyan

function Test-Url {
    param([string]$Name,[string]$Url)
    $code = curl.exe -s -o NUL -w "%{http_code}" $Url
    if ($code -eq "200") {
        Write-Host "$Name : PASS ($code)" -ForegroundColor Green
    } else {
        Write-Host "$Name : CHECK ($code)" -ForegroundColor Yellow
    }
}

Test-Url "Frontend" "http://localhost:5173/"
Test-Url "Dashboard API" "http://localhost:8000/api/v1/dashboard/overview"
Test-Url "Infrastructure API" "http://localhost:8000/api/v1/infrastructure?limit=3"
Test-Url "GIS API" "http://localhost:8000/api/v1/gis/assets?limit=3"
Test-Url "Inspections API" "http://localhost:8000/api/v1/inspections?limit=3"
Test-Url "Maintenance API" "http://localhost:8000/api/v1/maintenance?limit=3"
Test-Url "Predictions API" "http://localhost:8000/api/v1/predictions?limit=3"
Test-Url "Model Status" "http://localhost:8000/api/v1/analytics/models/status"
Test-Url "Reports Catalog" "http://localhost:8000/api/v1/reports/catalog"
Test-Url "Portfolio Report" "http://localhost:8000/api/v1/reports/portfolio/pdf"
Test-Url "High Risk CSV" "http://localhost:8000/api/v1/reports/high-risk/csv"

Write-Host "`n============================================================" -ForegroundColor Green
Write-Host "SIMRAS REAL-DATA FRONTEND + REPORTS INSTALLED" -ForegroundColor Green
Write-Host "============================================================" -ForegroundColor Green
Write-Host "Static analytics/infrastructure demo datasets archived."
Write-Host "Dashboard/AI/Analytics/Notifications/Reports now read backend data."
Write-Host "Missing prediction/evidence values remain N/A/withheld."
Write-Host "Backup: $backup"

Start-Process "http://localhost:5173/"
